// План specs/audit-log.md, 3.1 (кейс AL-05). Admin-dispatcher компании test. Только просмотр. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { openTeamChangeHistory, ADMIN_ONLY_EVENTS, DISPATCHER_EMAIL } from './audit-helpers';

test.use({ storageState: '../auth/dispatcher.json' });

test.describe('Team & Roles — Change history (#fc4fa4)', () => {
  test('Admin-dispatcher sees team events in Change history but no coupon or plan events #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openTeamChangeHistory(page);

    // История загружена: есть событие команды test по диспетчеру (Invited / Joined / Role changed — 11.11)
    const teamEvent = page.locator('tr, [role="row"]')
      .filter({ hasText: /Role changed|Joined|Invited/ })
      .filter({ hasText: DISPATCHER_EMAIL });
    await expect(teamEvent.first(), 'событие команды test в Change history').toBeVisible({ timeout: 30_000 });

    // Купонных и тарифных событий (только для супер-админа) нет
    await expect(page.getByText(ADMIN_ONLY_EVENTS)).toHaveCount(0);
  });
});
